#!/usr/bin/env bash
# ==============================================================================
# Itarang Phase 3 — poller hotfix v3
# Run as root on the Hostinger VPS from anywhere (uses absolute paths).
#
# Fixes:
#   Bug A: gps_t was silently falling back to now (via ts_to_dt's default arg)
#          when Intellicar returned data:null → last_gps_at got set to NOW.
#   Bug B: online was therefore computed True for the same vehicles → fleet
#          showed 257/261 "online" while only ~165 had real coordinates.
#   Coverage: added one short retry when Intellicar returns
#             {status:SUCCESS, data:null} — should recover most of the ~96
#             vehicles currently stuck without coordinates.
#
# What this script does:
#   1. Backs up current poll.py (timestamped)
#   2. Writes the new poll.py via base64 (md5 verified)
#   3. Rebuilds the poller image and restarts the container
#   4. Tails the log for ~75s and prints post-fix counts
# ==============================================================================
set -euo pipefail

STORAGE_DIR=/opt/intellicar/storage
POLL_FILE="$STORAGE_DIR/poller/poll.py"
EXPECTED_MD5="55d4e62cedb1566391e158a01f4122c2"

cd "$STORAGE_DIR"

echo "==> [1/4] Backing up current poller/poll.py"
cp "$POLL_FILE" "$POLL_FILE.bak.$(date +%s)"
ls -la "$STORAGE_DIR/poller/" | grep poll.py

echo "==> [2/4] Writing new poller/poll.py (base64, md5-verified)"
base64 -d > "$POLL_FILE" <<'B64_EOF'

B64_EOF

ACTUAL_MD5=$(md5sum "$POLL_FILE" | awk '{print $1}')
if [ "$ACTUAL_MD5" != "$EXPECTED_MD5" ]; then
  echo "    ERROR: md5 mismatch. expected=$EXPECTED_MD5 actual=$ACTUAL_MD5"
  echo "    File not applied. Restoring the most recent backup..."
  cp "$(ls -t $POLL_FILE.bak.* | head -1)" "$POLL_FILE"
  exit 1
fi
echo "    md5 ok ($ACTUAL_MD5)"
echo "    new file: $(wc -l < $POLL_FILE) lines"

echo "==> [3/4] Rebuilding poller image and restarting container"
docker compose build poller
docker compose up -d poller
docker compose ps poller

echo "==> [4/4] Tailing log for ~75s (3 poll cycles) to watch for errors"
timeout 75 docker compose logs --tail=0 -f poller || true

echo ""
echo "==> Post-fix counts (give the poller 60s before running this independently)"
docker compose exec -T postgres psql -U intellicar intellicar <<'SQL_EOF'
SELECT
  COUNT(*)                                AS total,
  COUNT(lat)                              AS with_lat,
  COUNT(soc_pct)                          AS with_soc,
  COUNT(*) FILTER (WHERE online)          AS online,
  COUNT(*) FILTER (WHERE online AND lat IS NULL) AS online_no_lat_BUG
FROM vehicle_state;

-- Should now be ~0
SELECT vehicleno, online, last_gps_at, lat, lon
FROM vehicle_state
WHERE online AND lat IS NULL
LIMIT 5;
SQL_EOF

echo ""
echo "================================================================="
echo " Hotfix v3 complete."
echo ""
echo " Expected outcome:"
echo "   online_no_lat_BUG should be 0 (was ~96 before)"
echo "   with_lat should climb closer to total thanks to retry-on-null"
echo "   online count will drop to match with_lat — that's correct"
echo ""
echo " Watch for a few cycles:"
echo "   cd  && docker compose logs -f --tail=20 poller"
echo "================================================================="
